	if opts.SegmentBytes <= 0 {
		return nil, ErrInvalidOptions
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var indices []int
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
			continue
		}
		n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
		if err != nil {
			continue
		}
		indices = append(indices, n)
	}
	sort.Ints(indices)

	l := &Log{
		dir:       dir,
		opts:      opts,
		nextSeq:   1,
		staged:    make(map[uint64][][]byte),
		committed: make(map[uint64][][]byte),
	}
	// curBatches must reflect only the newest file, so track that file's
	// complete-batch count separately across the loop.
	lastSegBatches := 0
	for i, n := range indices {
		path := l.segmentPath(n)
		data, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		batches, consumed, perr := parseSegment(data)
		if perr != nil {
			if i == len(indices)-1 && errors.Is(perr, errTrailingEntry) {
				// Crash tail in the newest segment: the last batch never
				// finished landing. Drop it as if it were never committed.
				if err := os.Truncate(path, int64(consumed)); err != nil {
					return nil, err
				}
			} else {
				return nil, ErrCorruptSegment
			}
		}
		lastSegBatches = len(batches)
		if len(batches) == 0 {
			continue // empty segment, e.g. created just before a crash
		}
		seg := Segment{FirstSeq: ^uint64(0)}
		for _, pb := range batches {
			l.committed[pb.seq] = pb.records
			if pb.seq < seg.FirstSeq {
				seg.FirstSeq = pb.seq
			}
			if pb.seq > seg.LastSeq {
				seg.LastSeq = pb.seq
			}
		}
		l.segs = append(l.segs, seg)
		if seg.LastSeq >= l.nextSeq {
			l.nextSeq = seg.LastSeq + 1
		}
	}
	if len(indices) > 0 {
		l.segIndex = indices[len(indices)-1]
		if err := l.openCurrent(); err != nil {
			return nil, err
		}
		l.curBatches = lastSegBatches
	}
	return l, nil
}

// Append stages a batch of records and reserves the next sequence number
// for it. The batch becomes readable only after Commit.
func (l *Log) Append(records [][]byte) (Batch, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return Batch{}, errClosed
	}
	recs := copyRecords(records)
	seq := l.nextSeq
	l.nextSeq++
	l.staged[seq] = recs
	return Batch{seq: seq, records: recs, owner: l}, nil
}

// Commit makes a staged batch durable and readable, and returns its
// reserved sequence number. Committing a batch that is not staged —
// including one already committed — returns ErrUnknownBatch.
//
